#include <bits/stdc++.h>

using namespace std;

int main() {
#ifdef _DEBUG
	freopen("input.txt", "r", stdin);
//	freopen("output.txt", "w", stdout);
#endif

	int n;
	cin >> n;
	vector<int> a(n);
	vector<int> cnt(200 * 1000 + 1);
	for (int i = 0; i < n; ++i) {
		cin >> a[i];
		++cnt[a[i]];
	}

	sort(a.begin(), a.end());
	a.resize(unique(a.begin(), a.end()) - a.begin());

	int l = 0, r = 0;
	int ans = cnt[a[0]];
	for (int i = 0; i < int(a.size()); ++i) {
		int j = i + 1;
		int sum = cnt[a[i]];
		while (a[j] - a[j - 1] == 1 && cnt[a[j]] > 1) {
			sum += cnt[a[j]];
			++j;
		}
		int cr = j - 1;
		if (j < n && a[j] - a[j - 1] == 1) {
			sum += cnt[a[j]];
			cr = j;
		}
		if (ans < sum) {
			ans = sum;
			l = i;
			r = cr;
		}
		i = j - 1;
	}

	cout << ans << endl;
	for (int c = 0; c < cnt[a[l]]; ++c) cout << a[l] << " ";
	for (int i = l + 1; i < r; ++i) {
		for (int c = 0; c < cnt[a[i]] - 1; ++c) cout << a[i] << " ";
	}
	for (int c = 0; l != r && c < cnt[a[r]]; ++c) cout << a[r] << " ";
	for (int i = r - 1; i > l; --i) cout << a[i] << " ";
	cout << endl;

	return 0;
}

#include <bits/stdc++.h>

using namespace std;

int n, m;

void invRow(vector<vector<int>> &a, int idx) {
	for (int pos = 0; pos < m; ++pos) {
		a[idx][pos] ^= 1;
	}
}

void invCol(vector<vector<int>> &a, int idx) {
	for (int pos = 0; pos < n; ++pos) {
		a[pos][idx] ^= 1;
	}
}

int main() {
#ifdef _DEBUG
	freopen("input.txt", "r", stdin);
//	freopen("output.txt", "w", stdout);
#endif

	cin >> n >> m;
	vector<vector<int>> a(n, vector<int>(m));
	for (int i = 0; i < n; ++i) {
		for (int j = 0; j < m; ++j) {
			cin >> a[i][j];
		}
	}

	for (int cnt0 = 0; cnt0 <= m; ++cnt0) {
		string r(n, '0');
		string c(m, '0');
		vector<vector<int>> b = a;
		for (int j = 0; j < m; ++j) {
			if ((j < cnt0 && b[0][j] == 1) || (j >= cnt0 && b[0][j] == 0)) {
				invCol(b, j);
				c[j] = '1';
			}
		}
		bool ok = true;
		if (cnt0 < m) {
			for (int i = 1; i < n; ++i) {
				int sum = accumulate(b[i].begin(), b[i].end(), 0);
				if (sum != 0 && sum != m) {
					ok = false;
				} else if (sum == 0) {
					invRow(b, i);
					r[i] = '1';
				}
			}
		} else {
			int idx = -1;
			for (int i = 1; i < n; ++i) {
				int sum = accumulate(b[i].begin(), b[i].end(), 0);
				if (sum != 0 && sum != m) {
					if (idx != -1) ok = false;
					else idx = i;
				}
			}
			if (idx == -1) {
				for (int i = 1; i < n; ++i) {
					int sum = accumulate(b[i].begin(), b[i].end(), 0);
					if (sum == 0) {
						invRow(b, i);
						r[i] = '1';
					}
				}
			} else {
				for (int i = 1; i < idx; ++i) {
					int sum = accumulate(b[i].begin(), b[i].end(), 0);
					if (sum == m) {
						invRow(b, i);
						r[i] = '1';
					}
				}
				if (b[idx][0] == 1) {
					invRow(b, idx);
					r[idx] = '1';
				}
				for (int j = 1; j < m; ++j) {
					if (b[idx][j] < b[idx][j - 1]) {
						ok = false;
					}
				}
				for (int i = idx + 1; i < n; ++i) {
					int sum = accumulate(b[i].begin(), b[i].end(), 0);
					if (sum == 0) {
						invRow(b, i);
						r[i] = '1';
					}
				}
			}
		}
		if (ok) {
			cout << "YES" << endl << r << endl << c << endl;
			return 0;
		}
	}

	cout << "NO" << endl;

	return 0;
}
